                    <v-col cols="12" sm="6">
                      <div class="ap-label">Start Date</div>
                      <div class="ap-value">
                        {{
                          fmtDate(subOf(eh, "start-date", "valueDate")) || "—"
                        }}
                      </div>
                    </v-col>
                    <v-col cols="12" sm="6">
                      <div class="ap-label">End Date</div>
                      <div class="ap-value">
                        {{ fmtDate(subOf(eh, "end-date", "valueDate")) || "—" }}
                      </div>
                    </v-col>
                    <v-col cols="12" sm="6">
