<script>
export default {
  name: "ApplicantProfile",

  data() {
    return {
      profile: null,
      loading: false,
      error: null,
      hasJobOffer: false,
    };
  },

  computed: {
    profileId() {
      return this.$route?.params?.id || this.$route?.query?.id;
    },

    extensions() {
      return this.profile?.extension || [];
    },

    fullName() {
      return (
        this.ext("ihris-basic-name") ||
        [this.ext("first-name"), this.ext("middle-name"), this.ext("surname")]
          .filter(Boolean)
          .join(" ") ||
        "Unknown Applicant"
      );
    },

    initials() {
      return this.fullName
        .split(" ")
        .slice(0, 2)
        .map((w) => w[0])
        .join("")
        .toUpperCase();
    },
  },

  created() {
    this.load();
  },

  methods: {
    async load() {
      if (!this.profileId) {
        this.error = "No profile ID provided.";
        return;
      }
      this.loading = true;
      this.error = null;
      try {
        const res = await fetch(`/fhir/Basic/${this.profileId}`);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        // Accept either a raw Basic resource or a Bundle
        if (data.resourceType === "Bundle") {
          this.profile = data.entry?.[0]?.resource || null;
        } else {
          this.profile = data;
        }
        if (!this.profile) throw new Error("No profile found.");
        await this.checkJobOffer();
      } catch (err) {
        this.error = err.message;
      } finally {
        this.loading = false;
      }
    },

    async checkJobOffer() {
      try {
        const res = await fetch(
          `/site/position/applied-positions?applicantid=${this.profileId}&_count=100`,
        );
        if (!res.ok) return;
        const data = await res.json();
        this.hasJobOffer = (data.applications || []).some(
          (a) => a.statusCode === "offered",
        );
      } catch (_) {
        /* non-blocking — default is editable */
      }
    },

    // ── Extension helpers ───────────────────────────────────────────

    /** Get the value of a top-level extension by the last segment of its URL */
    ext(urlSuffix, field = "valueString") {
      const e = this.extensions.find((x) => x.url.endsWith("/" + urlSuffix));
      return e ? e[field] ?? null : null;
    },

    /** Get the display of a coding extension */
    extCoding(urlSuffix) {
      const e = this.extensions.find((x) => x.url.endsWith("/" + urlSuffix));
      return e?.valueCoding?.display ?? null;
    },

    /** Get the display label of a reference extension (Location / Basic) */
    extRef(urlSuffix) {
      const e = this.extensions.find((x) => x.url.endsWith("/" + urlSuffix));
      if (!e?.valueReference) return null;
      return e.valueReference.display || e.valueReference.reference || null;
    },

    /** Get the display label of a reference sub-extension */
    subOfRef(extEntry, subUrl) {
      if (!extEntry?.extension) return null;
      const child = extEntry.extension.find((x) => x.url === subUrl);
      if (!child?.valueReference) return null;
      return child.valueReference.display || child.valueReference.reference || null;
    },

    /** Get a nested extension object (returns the extension entry itself) */
    nestedExt(urlSuffix) {
      return (
        this.extensions.find((x) => x.url.endsWith("/" + urlSuffix)) ?? null
      );
    },

    /** Get a string sub-extension value from a nested extension */
    nestedSub(urlSuffix, subUrl, field = "valueString") {
      const parent = this.nestedExt(urlSuffix);
      if (!parent?.extension) return null;
      const child = parent.extension.find((x) => x.url === subUrl);
      return child ? child[field] ?? null : null;
    },

    /** Get a coding display from a sub-extension */
    nestedSubCoding(urlSuffix, subUrl) {
      const parent = this.nestedExt(urlSuffix);
      if (!parent?.extension) return null;
      const child = parent.extension.find((x) => x.url === subUrl);
      return child?.valueCoding?.display ?? null;
    },

    /** Get all repeating extensions with a given URL suffix */
    allExts(urlSuffix) {
      return this.extensions.filter((x) => x.url.endsWith("/" + urlSuffix));
    },

    /** Get a sub-extension value from a repeating extension entry */
    subOf(extEntry, subUrl, field = "valueString") {
      if (!extEntry?.extension) return null;
      const child = extEntry.extension.find((x) => x.url === subUrl);
      return child ? child[field] ?? null : null;
    },

    /** Get the display of a coding sub-extension */
    subOfCoding(extEntry, subUrl) {
      if (!extEntry?.extension) return null;
      const child = extEntry.extension.find((x) => x.url === subUrl);
      return child?.valueCoding?.display || child?.valueCoding?.code || null;
    },

    /** Format a YYYY-MM-DD date for display */
    fmtDate(val) {
      if (!val) return null;
      try {
        const [y, m, d] = val.split("T")[0].split("-");
        if (!y) return val;
        if (!m) return y;
        if (!d) return `${this.monthName(m)} ${y}`;
        return `${parseInt(d, 10)} ${this.monthName(m)} ${y}`;
      } catch {
        return val;
      }
    },

    monthName(m) {
      const names = [
        "Jan",
        "Feb",
        "Mar",
        "Apr",
        "May",
        "Jun",
        "Jul",
        "Aug",
        "Sep",
        "Oct",
        "Nov",
        "Dec",
      ];
      return names[parseInt(m, 10) - 1] || m;
    },

    editProfile() {
      this.$router.push({
        path: "/custom/signup",
        query: {
          path: "/lesotho/components/recruitment",
          editId: this.profileId,
        },
      });
    },

    yesNoBadge(val) {
      if (!val) return "";
      const v = val.toLowerCase();
      if (v === "yes") return "ap-badge--red";
      if (v === "no") return "ap-badge--green";
      return "";
    },
  },
};
</script>

